"use client";

import { fetchExamsFromDb } from "@/lib/exams/api";
import type { ParsedExamRecord } from "@/lib/exams/parseWorkbook";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

type MeResponse = {
  user: {
    id: string;
    email: string;
    name: string | null;
    role: string;
  } | null;
};

type ViewMode = "session" | "room";

type SessionGroup = {
  key: string;
  courseCode: string;
  courseName: string | null;
  examDate: string | null;
  startTime: string | null;
  room: string | null;
  campus: string | null;
  records: ParsedExamRecord[];
};

function normalizeSpace(value: unknown) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function normalizeText(value: unknown) {
  return normalizeSpace(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase();
}

function formatDate(value: string | null) {
  if (!value) return "—";
  const d = new Date(`${value}T00:00:00`);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleDateString("vi-VN");
}

function formatDateTime(date: string | null, time: string | null) {
  return `${formatDate(date)}${time ? ` • ${time}` : ""}`;
}

function buildSessionKey(record: ParsedExamRecord) {
  return [
    record.courseCode || "",
    record.examDate || "",
    record.startTime || "",
    record.room || "",
    record.campus || "",
  ].join("||");
}

function buildSessionGroups(records: ParsedExamRecord[]): SessionGroup[] {
  const map = new Map<string, SessionGroup>();

  for (const record of records) {
    const key = buildSessionKey(record);

    if (!map.has(key)) {
      map.set(key, {
        key,
        courseCode: record.courseCode,
        courseName: record.courseName,
        examDate: record.examDate,
        startTime: record.startTime,
        room: record.room,
        campus: record.campus,
        records: [],
      });
    }

    map.get(key)!.records.push(record);
  }

  return Array.from(map.values()).sort((a, b) => {
    const av = `${a.examDate || "9999-12-31"} ${a.startTime || "23:59"} ${a.room || ""}`;
    const bv = `${b.examDate || "9999-12-31"} ${b.startTime || "23:59"} ${b.room || ""}`;
    return av.localeCompare(bv);
  });
}

function getNoticeReportHref(detailUrl: string) {
  return `/exams/report?notice=${encodeURIComponent(detailUrl)}`;
}

function getRoomLabel(room: string | null, campus: string | null) {
  const roomText = normalizeSpace(room) || "Chưa rõ phòng";
  const campusText = normalizeSpace(campus);
  return campusText ? `${roomText} • ${campusText}` : roomText;
}

function buildClassOptions(records: ParsedExamRecord[]) {
  return Array.from(
    new Set(
      records
        .flatMap((x) => [x.classCourse, x.classStudent])
        .map((x) => normalizeSpace(x))
        .filter(Boolean),
    ),
  ).sort((a, b) => a.localeCompare(b));
}

function buildRoomOptions(records: ParsedExamRecord[]) {
  return Array.from(
    new Set(records.map((x) => getRoomLabel(x.room, x.campus)).filter(Boolean)),
  ).sort((a, b) => a.localeCompare(b));
}

function getUpcomingLabel(date: string | null) {
  if (!date) return "Chưa rõ ngày";
  const today = new Date();
  const base = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime();
  const exam = new Date(`${date}T00:00:00`).getTime();

  if (Number.isNaN(exam)) return "Chưa rõ ngày";

  const diff = Math.round((exam - base) / 86400000);
  if (diff > 0) return `Còn ${diff} ngày`;
  if (diff === 0) return "Hôm nay";
  return `Đã qua ${Math.abs(diff)} ngày`;
}

async function fetchCurrentUserId(): Promise<string | null> {
  try {
    const res = await fetch("/api/auth/me", {
      method: "GET",
      credentials: "include",
      cache: "no-store",
    });

    if (!res.ok) return null;
    const json = (await res.json()) as MeResponse;
    return json?.user?.id ?? null;
  } catch {
    return null;
  }
}

