  "inline-flex h-11 items-center justify-center rounded-2xl border border-[#dbe5f3] bg-white px-4 text-sm font-bold text-[#16325c] shadow-[0_10px_24px_rgba(15,23,42,0.08)] transition hover:-translate-y-[1px] hover:bg-[#f8fbff]";

const BTN_PRIMARY =
  "inline-flex h-11 items-center justify-center rounded-2xl border border-transparent bg-[linear-gradient(180deg,#6ea3ff_0%,#3b82f6_100%)] px-4 text-sm font-bold text-white shadow-[0_16px_34px_rgba(59,130,246,0.28)] transition hover:-translate-y-[1px] hover:brightness-105";

const BTN_PRIMARY_ACTIVE =
  "inline-flex h-11 items-center justify-center rounded-2xl border border-transparent bg-[linear-gradient(180deg,#6ea3ff_0%,#3b82f6_100%)] px-4 text-sm font-bold text-white shadow-[0_16px_34px_rgba(59,130,246,0.28)] transition";

const BTN_SOFT =
  "inline-flex h-10 items-center justify-center rounded-xl border border-[var(--border-main)] bg-[rgba(255,255,255,0.045)] px-4 text-sm font-bold text-[var(--text-main)] shadow-[0_8px_20px_rgba(2,8,23,0.14)] transition hover:-translate-y-[1px] hover:bg-[rgba(255,255,255,0.07)]";

function ActionHint({ text }: { text: string }) {
  return (
    <div className="mt-2 text-[12px] leading-5 text-[var(--text-muted)]">
      {text}
    </div>
  );
}

export default function ExamReportPage() {
  const searchParams = useSearchParams();
  const notice = searchParams.get("notice") || "";

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [records, setRecords] = useState<ParsedExamRecord[]>([]);
  const [query, setQuery] = useState("");
  const [roomFilter, setRoomFilter] = useState("all");
  const [classFilter, setClassFilter] = useState("all");
  const [sessionFilter, setSessionFilter] = useState("all");
  const [viewMode, setViewMode] = useState<ViewMode>("session");
  const [activeSession, setActiveSession] = useState<SessionGroup | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function boot() {
      setLoading(true);
      setError(null);

      try {
        if (!notice) {
          throw new Error("Thiếu tham số notice.");
        }

        const userId = await fetchCurrentUserId();
        if (!userId) {
          throw new Error("Không xác định được người dùng hiện tại.");
        }

        const all = await fetchExamsFromDb({ userId });
        const scoped = all.filter((x) => x.detailUrl === notice);

        if (!cancelled) {
          setRecords(scoped);
        }
      } catch (e) {
        if (!cancelled) {
          setError(String((e as Error)?.message || e));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    }

    boot();
    return () => {
      cancelled = true;
    };
  }, [notice]);

  const roomOptions = useMemo(() => buildRoomOptions(records), [records]);
  const classOptions = useMemo(() => buildClassOptions(records), [records]);
  const filteredRecords = useMemo(() => {
    const q = normalizeText(query);

    return records.filter((record) => {
      const roomLabel = getRoomLabel(record.room, record.campus);
      const classes = [record.classCourse, record.classStudent]
        .map((x) => normalizeSpace(x))
        .filter(Boolean);

      const matchesQuery =
        !q ||
        [
          record.studentId,
          record.studentName,
          record.courseCode,
          record.courseName,
          record.room,
          record.campus,
          record.classCourse,
          record.classStudent,
        ]
          .map(normalizeText)
          .some((x) => x.includes(q));

      const matchesRoom = roomFilter === "all" || roomLabel === roomFilter;
      const matchesClass = classFilter === "all" || classes.includes(classFilter);
      const matchesSession =
        sessionFilter === "all" || buildSessionKey(record) === sessionFilter;

      return matchesQuery && matchesRoom && matchesClass && matchesSession;
    });
  }, [records, query, roomFilter, classFilter, sessionFilter]);

  const filteredSessions = useMemo(
    () => buildSessionGroups(filteredRecords),
    [filteredRecords],
  );

  const sessionOptions = useMemo(() => {
    return filteredSessions.map((session) => ({
      value: session.key,
      label: `${session.courseCode} • ${formatDateTime(
        session.examDate,
        session.startTime,
      )} • ${getRoomLabel(session.room, session.campus)}`,
    }));
  }, [filteredSessions]);

  const groupedByRoom = useMemo(() => {
    const map = new Map<string, SessionGroup[]>();

    for (const session of filteredSessions) {
      const key = getRoomLabel(session.room, session.campus);
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(session);
    }

    return Array.from(map.entries());
  }, [filteredSessions]);

  function resetFilters() {
    setQuery("");
    setRoomFilter("all");
    setClassFilter("all");
    setSessionFilter("all");
  }

  async function copyStudentIds(session: SessionGroup) {
    const text = session.records
      .map((x) => normalizeSpace(x.studentId))
      .filter(Boolean)
      .join("\n");

    try {
      await navigator.clipboard.writeText(text);
      alert("Đã copy danh sách MSSV.");
    } catch {
      alert("Không copy được danh sách MSSV.");
    }
  }

  const headerTitle =
    records[0]?.courseCode || records[0]?.noticeTitle || "Hồ sơ lịch thi";

  return (
    <div className="space-y-5">
      <section className="app-section p-5 md:p-6">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <div className="text-[1.9rem] font-bold tracking-tight">
              {headerTitle}
            </div>
            <div className="mt-1.5 text-sm text-[var(--text-muted)]">
              Giữ nguyên cấu trúc file của trường nhưng hiển thị gọn, rõ, tách
              cột tốt hơn cho Excel và PDF.
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={() => setViewMode("session")}
              className={viewMode === "session" ? BTN_PRIMARY_ACTIVE : BTN_NEUTRAL}
              title="Xem danh sách theo từng phiên thi"
            >
              Theo phiên thi
            </button>
            <button
              type="button"
              onClick={() => setViewMode("room")}
              className={viewMode === "room" ? BTN_PRIMARY_ACTIVE : BTN_NEUTRAL}
              title="Xem danh sách theo nhóm phòng thi"
            >
              Theo phòng thi
            </button>
          </div>
        </div>

        <div className="mt-5 rounded-[28px] border border-[var(--border-main)] bg-[var(--bg-soft)]/55 p-4 md:p-5">
          <div className="mb-4">
            <div className="text-[1.05rem] font-bold text-[var(--text-main)]">
              Bộ lọc hồ sơ lịch
            </div>
            <div className="mt-1 text-sm text-[var(--text-muted)]">
              Tìm MSSV, họ tên, lớp, môn, phòng. Có thêm nút đặt lại để trả bộ
              lọc về trạng thái ban đầu.
            </div>
          </div>

          <div className="grid grid-cols-1 gap-3 xl:grid-cols-12">
            <div className="xl:col-span-4">
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Tìm MSSV, họ tên, lớp, môn, phòng..."
                className="app-input h-14 w-full rounded-[22px] px-5 text-[15px] font-semibold text-[var(--text-main)]"
              />
            </div>

            <div className="xl:col-span-3">
              <select
                value={roomFilter}
                onChange={(e) => setRoomFilter(e.target.value)}
                className="app-input h-14 w-full rounded-[22px] px-5 text-[15px] font-semibold text-[var(--text-main)]"
              >
                <option value="all">Tất cả phòng</option>
                {roomOptions.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
            </div>

            <div className="xl:col-span-2">
              <select
                value={classFilter}
                onChange={(e) => setClassFilter(e.target.value)}
                className="app-input h-14 w-full rounded-[22px] px-5 text-[15px] font-semibold text-[var(--text-main)]"
              >
                <option value="all">Tất cả lớp</option>
                {classOptions.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
            </div>

            <div className="xl:col-span-2">
              <select
                value={sessionFilter}
                onChange={(e) => setSessionFilter(e.target.value)}
                className="app-input h-14 w-full rounded-[22px] px-5 text-[15px] font-semibold text-[var(--text-main)]"
              >
                <option value="all">Tất cả phiên thi</option>
                {sessionOptions.map((x) => (
                  <option key={x.value} value={x.value}>
                    {x.label}
                  </option>
                ))}
              </select>
            </div>

            <div className="xl:col-span-1">
              <button
                type="button"
                onClick={resetFilters}
                className={`${BTN_NEUTRAL} h-14 w-full`}
                title="Đặt lại toàn bộ bộ lọc"
              >
                Đặt lại
              </button>
            </div>
          </div>
        </div>
      </section>

      {loading ? (
        <section className="app-section p-6 text-sm text-[var(--text-muted)]">
          Đang tải hồ sơ lịch...
        </section>
      ) : error ? (
        <section className="app-section p-6 text-sm text-[var(--danger)]">
          {error}
        </section>
      ) : filteredSessions.length === 0 ? (
        <section className="app-section p-6 text-sm text-[var(--text-muted)]">
          Không có dữ liệu phù hợp.
        </section>
      ) : viewMode === "session" ? (
        <section className="space-y-4">
          {filteredSessions.map((session) => (
            <div key={session.key} className="app-section overflow-hidden">
              <div className="border-b border-[var(--border-main)] px-5 py-5">
                <div className="grid gap-4 lg:grid-cols-[1.5fr_1.2fr_0.8fr_1fr] xl:grid-cols-[1.5fr_1fr_0.8fr_1.2fr_1.3fr]">
                  <div>
                    <div className="text-[1.65rem] font-bold">
                      {session.courseCode || "—"}
                    </div>
                    <div className="mt-1 text-sm text-[var(--text-muted)]">
                      {session.courseName || "—"}
                    </div>
                  </div>

                  <div>
                    <div className="text-[1.05rem] font-bold">
                      {formatDateTime(session.examDate, session.startTime)}
                    </div>
                    <div className="mt-2 text-sm text-[var(--text-muted)]">
                      {session.records[0]?.examMetaRaw || "Chưa có meta chi tiết"}
                    </div>
                  </div>

                  <div className="flex flex-wrap items-start gap-2">
                    <span className="inline-flex rounded-full bg-[var(--accent)]/14 px-4 py-2 text-sm font-bold text-[var(--accent)]">
                      {getUpcomingLabel(session.examDate)}
                    </span>
                    <span className="inline-flex rounded-full bg-[var(--bg-soft)] px-4 py-2 text-sm font-bold text-[var(--text-main)]">
                      {session.records.length} sinh viên
                    </span>
                  </div>

                  <div>
                    <div className="text-sm font-bold text-[var(--text-main)]">
                      {getRoomLabel(session.room, session.campus)}
                    </div>
                    <div className="mt-2 space-y-1 text-sm text-[var(--text-muted)]">
                      <div>
                        Lớp môn học:{" "}
                        <span className="font-semibold text-[var(--text-main)]">
                          {new Set(session.records.map((x) => x.classCourse).filter(Boolean)).size}
                        </span>
                      </div>
                      <div>
                        Lớp sinh hoạt:{" "}
                        <span className="font-semibold text-[var(--text-main)]">
                          {new Set(session.records.map((x) => x.classStudent).filter(Boolean)).size}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div className="flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => setActiveSession(session)}
                        className={BTN_NEUTRAL}
                        title="Xem danh sách sinh viên của riêng phiên thi này"
                      >
                        Xem ca thi
                      </button>

                      <button
                        type="button"
                        onClick={() => copyStudentIds(session)}
                        className={BTN_SOFT}
                        title="Copy nhanh toàn bộ MSSV trong phiên thi này"
                      >
                        Copy danh sách MSSV
                      </button>

                      <Link
                        href={getNoticeReportHref(session.records[0]?.detailUrl || "")}
                        className={BTN_PRIMARY}
                        title="Mở toàn bộ hồ sơ lịch của file nguồn"
                      >
                        Mở hồ sơ lịch
                      </Link>
                    </div>

                    <ActionHint text="Xem ca thi: mở danh sách sinh viên của phiên đang chọn. Mở hồ sơ lịch: xem toàn bộ file nguồn ở dạng web gọn hơn PDF/Excel gốc." />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </section>
      ) : (
        <section className="space-y-4">
          {groupedByRoom.map(([roomLabel, sessions]) => (
            <div key={roomLabel} className="app-section overflow-hidden">
              <div className="border-b border-[var(--border-main)] px-5 py-4">
                <div className="text-[1.2rem] font-bold">{roomLabel}</div>
                <div className="mt-1 text-sm text-[var(--text-muted)]">
                  {sessions.length} phiên thi trong nhóm phòng này
                </div>
              </div>

              <div className="divide-y divide-[var(--border-main)]">
                {sessions.map((session) => (
                  <div key={session.key} className="px-5 py-4">
                    <div className="grid gap-4 lg:grid-cols-[1.1fr_0.9fr_0.7fr_1.2fr]">
                      <div>
                        <div className="text-lg font-bold">{session.courseCode}</div>
                        <div className="mt-1 text-sm text-[var(--text-muted)]">
                          {session.courseName || "—"}
                        </div>
                      </div>

                      <div>
                        <div className="text-base font-bold">
                          {formatDateTime(session.examDate, session.startTime)}
                        </div>
                        <div className="mt-1 text-sm text-[var(--text-muted)]">
                          {session.records[0]?.examMetaRaw || "—"}
                        </div>
                      </div>

                      <div className="inline-flex w-fit rounded-full bg-[var(--bg-soft)] px-4 py-2 text-sm font-bold text-[var(--text-main)]">
                        {session.records.length} sinh viên
                      </div>

                      <div className="space-y-2">
                        <div className="flex flex-wrap gap-2">
                          <button
                            type="button"
                            onClick={() => setActiveSession(session)}
                            className={BTN_NEUTRAL}
                          >
                            Xem ca thi
                          </button>
                          <Link
                            href={getNoticeReportHref(session.records[0]?.detailUrl || "")}
                            className={BTN_PRIMARY}
                          >
                            Mở hồ sơ lịch
                          </Link>
                        </div>
                        <ActionHint text="Nhóm theo phòng giúp dò nhanh phòng nào đang chứa những phiên thi nào." />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </section>
      )}

      {activeSession ? (
        <div className="fixed inset-0 z-50 bg-black/55 p-4">
          <div className="mx-auto flex h-full max-w-7xl items-start justify-center">
            <div className="mt-6 max-h-[90vh] w-full overflow-hidden rounded-[28px] border border-[var(--border-main)] bg-[var(--bg-card)] shadow-2xl">
              <div className="flex items-start justify-between gap-4 border-b border-[var(--border-main)] px-5 py-4">
                <div className="min-w-0">
                  <div className="text-[1.4rem] font-bold">
                    {activeSession.courseCode}
                  </div>
                  <div className="mt-1 text-sm text-[var(--text-muted)]">
                    {formatDateTime(activeSession.examDate, activeSession.startTime)} •{" "}
                    {getRoomLabel(activeSession.room, activeSession.campus)}
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => setActiveSession(null)}
                  className={BTN_NEUTRAL}
                >
                  Đóng
                </button>
              </div>

              <div className="max-h-[calc(90vh-88px)] overflow-auto px-5 py-4">
                <div className="mb-4 grid gap-3 md:grid-cols-4">
                  <div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
                    <div className="text-[11px] uppercase text-[var(--text-muted)]">
                      Môn học
                    </div>
                    <div className="mt-1 font-bold">{activeSession.courseCode}</div>
                  </div>

                  <div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
                    <div className="text-[11px] uppercase text-[var(--text-muted)]">
                      Phiên thi
                    </div>
                    <div className="mt-1 font-bold">
                      {formatDateTime(activeSession.examDate, activeSession.startTime)}
                    </div>
                  </div>

                  <div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
                    <div className="text-[11px] uppercase text-[var(--text-muted)]">
                      Phòng
                    </div>
                    <div className="mt-1 font-bold">
                      {getRoomLabel(activeSession.room, activeSession.campus)}
                    </div>
                  </div>

                  <div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
                    <div className="text-[11px] uppercase text-[var(--text-muted)]">
                      Số sinh viên
                    </div>
                    <div className="mt-1 font-bold">{activeSession.records.length}</div>
                  </div>
                </div>

                <div className="mb-4 flex flex-wrap gap-2">
                  <button
                    type="button"
                    onClick={() => copyStudentIds(activeSession)}
                    className={BTN_SOFT}
                  >
                    Copy danh sách MSSV
                  </button>

                  <a
                    href={activeSession.records[0]?.detailUrl || "#"}
                    target="_blank"
                    rel="noreferrer"
                    className={BTN_SOFT}
                  >
                    Mở link chi tiết gốc
                  </a>

                  {activeSession.records[0]?.attachmentUrl ? (
                    <a
                      href={activeSession.records[0]?.attachmentUrl || "#"}
                      target="_blank"
                      rel="noreferrer"
                      className={BTN_PRIMARY}
                    >
                      Mở file gốc
                    </a>
                  ) : null}
                </div>

                <div className="overflow-auto rounded-[24px] border border-[var(--border-main)]">
                  <table className="min-w-[1080px] w-full text-sm">
                    <thead className="bg-[var(--bg-soft)]">
                      <tr className="text-left">
                        <th className="px-4 py-3 font-bold">STT</th>
                        <th className="px-4 py-3 font-bold">MSSV</th>
                        <th className="px-4 py-3 font-bold">Họ tên</th>
                        <th className="px-4 py-3 font-bold">Lớp môn học</th>
                        <th className="px-4 py-3 font-bold">Lớp sinh hoạt</th>
                        <th className="px-4 py-3 font-bold">Ngày sinh</th>
                        <th className="px-4 py-3 font-bold">Ghi chú</th>
                      </tr>
                    </thead>
                    <tbody>
                      {activeSession.records.map((row, index) => (
                        <tr
                          key={row.id}
                          className="border-t border-[var(--border-main)]"
                        >
                          <td className="px-4 py-3 align-top">{index + 1}</td>
                          <td className="px-4 py-3 align-top font-medium">
                            {row.studentId || "—"}
                          </td>
                          <td className="px-4 py-3 align-top font-medium">
                            {row.studentName || "—"}
                          </td>
                          <td className="px-4 py-3 align-top">
                            {row.classCourse || "—"}
                          </td>
                          <td className="px-4 py-3 align-top">
                            {row.classStudent || "—"}
                          </td>
                          <td className="px-4 py-3 align-top">
                            {row.birthDate ? formatDate(row.birthDate) : "—"}
                          </td>
                          <td className="px-4 py-3 align-top">
                            {row.note || "—"}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                <div className="mt-3 text-sm text-[var(--text-muted)]">
                  Bản xem này chỉ hiển thị riêng một ca thi. Muốn xem cả file nguồn
                  theo cấu trúc lớn hơn thì dùng nút “Mở hồ sơ lịch”.
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}